import {readFile,writeFile} from 'node:fs/promises';
import {root,lerRodadas,matrizConcluida} from './dados-regressao-servicos-20261116.mjs';
const ler=async p=>{try{return JSON.parse(await readFile(root+'/'+p,'utf8'))}catch{return null}};
const rodadas=await lerRodadas(),docs=await matrizConcluida();
const nomes={assistencia_geral:'Assistência geral',assistencia_celulares:'Celulares e tablets',assistencia_informatica:'Informática',assistencia_eletrodomesticos:'Eletrodomésticos',assistencia_eletronica:'Eletrônica e placas',manutencao_geral:'Manutenção geral',manutencao_climatizacao:'Climatização',manutencao_eletrica:'Elétrica',manutencao_hidraulica:'Hidráulica',manutencao_equipamentos:'Equipamentos',limpeza_geral:'Limpeza geral',limpeza_residencial:'Limpeza residencial',limpeza_comercial:'Limpeza comercial',limpeza_pos_obra:'Limpeza pós-obra',limpeza_estofados:'Estofados',limpeza_vidros:'Vidros'};
const grupos={assistencia_tecnica:'Assistência técnica',manutencao_campo:'Manutenção de campo',limpeza:'Limpeza'};
const arquivos={assistencia_tecnica:'assistencia.html',manutencao_campo:'manutencao.html',limpeza:'limpeza.html'};
const pertence=(j,d,x)=>d.pasta===j.pasta&&d.perfil===x.perfil&&d.width===x.width&&d.caso===x.caso;
const tempos=rodadas.flatMap(j=>j.resultados.filter(x=>docs.some(d=>pertence(j,d,x))).map(x=>({...x,pasta:j.pasta})));
const checks=rodadas.flatMap(j=>j.checks.filter(x=>docs.some(d=>pertence(j,d,x))));
const falhas=rodadas.flatMap(j=>j.falhas.map(f=>({...f,pasta:j.pasta})));
const banco=await Promise.all(Object.keys(nomes).map(async perfil=>({perfil,...await ler('banco/'+perfil+'.json')})));
const ciclo=await Promise.all(Object.keys(nomes).map(async perfil=>({perfil,...await ler('banco/ui-'+perfil+'.json')})));
const excecoes=await ler('excecoes/resultados.json'),pdfs=await ler('pdfs-conferencia.json'),suites=await ler('regressao/resultado.json'),publicacao=await ler('publicacao.json'),busca=await ler('recuperacao-busca-publicado/resultados.json'),login=await ler('login-publicado/resultados.json');
const concorrencia=await ler('concorrencia-publicado/resultado.json');
const pct=(xs,p)=>{if(!xs.length)return null;const a=[...xs].sort((x,y)=>x-y);return a[Math.max(0,Math.ceil(a.length*p)-1)]};
const stats=xs=>{const a=[...xs].sort((x,y)=>x-y),m=Math.floor(a.length/2);return{n:a.length,mediana:a.length?(a.length%2?a[m]:(a[m-1]+a[m])/2):null,p95:pct(a,.95),maximo:a.length?a.at(-1):null}};
const resumo=Object.fromEntries(Object.keys(grupos).map(g=>[g,{nome:grupos[g],documentos:docs.filter(d=>d.ramo===g).length,operacoes:tempos.filter(t=>t.ramo===g).length,tempos:Object.fromEntries([...new Set(tempos.map(t=>t.nome))].map(n=>[n,stats(tempos.filter(t=>t.ramo===g&&t.nome===n).map(t=>t.segundos))]))}]));
const sum={geradoEm:new Date().toISOString(),nomes,grupos,resumo,documentos:docs,tempos,checks:checks.length,falhas,banco:banco.map(b=>({perfil:b.perfil,ok:b.ok,checks:b.checks?.length||0,tempos:b.tempos,falha:b.falha,falhasAnteriores:b.falhasAnteriores})),ciclo:ciclo.map(b=>({perfil:b.perfil,build:b.build,ok:b.ok,checks:b.checks?.length||0,falha:b.falha})),excecoes,busca,login,concorrencia,pdfs:pdfs?.resultados.length,suites:suites?.resultados.length,suitesOk:suites?.resultados.filter(x=>x.sucesso).length,publicacao};
await writeFile(root+'/sumario.json',JSON.stringify(sum,null,2));
const esc=s=>String(s??'—').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const sec=n=>n==null?'—':n.toFixed(3).replace('.',',')+' s';
const table=(heads,rows)=>`<div class="tabela"><table><thead><tr>${heads.map(h=>'<th>'+esc(h)+'</th>').join('')}</tr></thead><tbody>${rows.map(row=>'<tr>'+row.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`;
const header=(title,body)=>`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>*{box-sizing:border-box}body{font:16px/1.6 system-ui,sans-serif;color:#19352c;background:#eef3ef;margin:0}main{max-width:1280px;margin:auto;padding:36px 22px 80px}h1{font-size:36px;line-height:1.2}h2{margin-top:36px}h3{margin-top:24px}a{color:#156b50}nav{display:flex;gap:20px;flex-wrap:wrap}.card{background:white;border:1px solid #ccd9d0;border-radius:14px;padding:24px;margin:22px 0}.alerta{border-left:5px solid #b87913;background:#fff8e9}.ok{color:#177151;font-weight:bold}.tabela{overflow:auto;border:1px solid #c5d4ca;border-radius:10px;margin:18px 0}table{border-collapse:collapse;width:100%;background:white}th{background:#193f31;color:white;text-align:left}th,td{padding:11px 14px;border-bottom:1px solid #d4dfd7;vertical-align:top}tr:nth-child(even){background:#f2f6f3}input{font:inherit;padding:12px;max-width:100%;width:480px;border:1px solid #a9bfae;border-radius:8px}summary{cursor:pointer;font-weight:bold}small{color:#53675a}code{overflow-wrap:anywhere}img{max-width:100%;border:1px solid #ccd9d0;border-radius:10px}.metricas{display:flex;gap:24px;flex-wrap:wrap}.metricas b{font-size:28px;display:block}.metricas>div{flex:1;min-width:160px}@media(max-width:600px){main{padding:22px 12px}h1{font-size:28px}.card{padding:16px}th,td{padding:9px}}@media print{body{background:white}main{padding:0}nav,input{display:none}.tabela{overflow:visible}h2,h3{break-after:avoid}tr{break-inside:avoid}}</style><main><nav><a href="relatorio.html">Resumo</a>${Object.entries(arquivos).map(([g,f])=>`<a href="${f}">${grupos[g]}</a>`).join('')}</nav><h1>${esc(title)}</h1><p>Rodada de 16/11/2026 · Site publicado · Empresas fictícias “ZZ [TESTE 20261019]”</p>${body}</main></html>`;
const method=`<section class="card"><h2>O que os segundos significam</h2><p>Tempo medido pela automação, desde a primeira ação até a confirmação visível. Inclui preenchimento rápido, cliques e esperas pela rede; não representa o tempo de digitação de uma pessoa. Consultas usam o cache normal do produto. Desktop: 1920×1080. Celular: Chromium com toque, tela 390×844 e escala 2; não é um aparelho físico. As verificações complementares usam também 320 px.</p><p>A rodada inicial usou três navegadores e um roteiro de API em paralelo. Após timeouts, os casos pendentes foram repetidos sequencialmente. Cada registro identifica a rodada; não há alegação de ganho antes/depois nem homologação de carga de produção.</p><p><b>Simples:</b> cliente, equipamento/local e um serviço de catálogo. <b>Completo:</b> 12 itens (catálogo, estoque e dez avulsos), quantidades, desconto, data, custos, descrição, observações e ficha específica. Cada documento passa por consulta por número, cliente e equipamento/local; edição de valores e ficha; recarga; histórico e PDF.</p></section>`;
let body=`<section class="card metricas"><div><b>${docs.length}/128</b>casos completos de criação, edição e consulta</div><div><b>${checks.length}</b>verificações desses casos</div><div><b>${Object.keys(nomes).length}</b>subsistemas previstos</div><div><b>${tempos.length}</b>operações cronometradas</div></section>`;
body+=`<section class="card alerta"><h2>Estabilidade do servidor</h2><p>Ocorreram erros reais de tempo limite (57014) na rodada simultânea, inclusive em leituras e validação de acesso. Foram consultados logs, estatísticas e o diagnóstico de saúde do Supabase. As tentativas originais permanecem no relatório. Aprovação funcional dos retestes não significa que a causa de toda indisponibilidade foi eliminada.</p><p>Uma correção distingue falha de infraestrutura de senha inválida na entrada. Não foram acrescentadas repetições automáticas de pagamentos nem alteradas permissões para contornar erros.</p></section>`;
body+=table(['Grupo','Casos completos','Operações medidas','Relatório'],Object.entries(resumo).map(([g,r])=>[esc(r.nome),r.documentos,r.operacoes,`<a href="${arquivos[g]}">Abrir testes e tempos</a>`]));
body+=method+'<p>CPU e rede são as do computador de teste, sem limitação artificial. Não houve teste em Safari ou aparelho físico. A impressão foi validada por abertura da nota e arquivo PDF; não foi usada impressora de papel.</p>';
body+='<h2>Correções publicadas</h2>'+table(['Problema','Correção','Arquivos'],[
 ['Falha no servidor apresentada como senha incorreta','Mensagens distintas para indisponibilidade, rede, limite de tentativas, e-mail não confirmado e credencial inválida.','src/auth/erroEntrada.ts; src/pages/Entrar.tsx'],
 ['Busca sem recuperação direta após erro','Botão Tentar novamente mantém o termo, o formulário e o foco; a busca não repete silenciosamente uma espera longa. Referência ativa do teclado é removida durante erro/carregamento.','src/components/SelecaoRapida.tsx; src/components/servicos/SelecaoOperacao.tsx'],
 ['Nome selecionado ficava momentaneamente vazio enquanto era consultado novamente','O registro já encontrado é guardado no cache por empresa, tipo, cliente e ID. Evita consulta repetida por ID.','src/components/servicos/SelecaoOperacao.tsx']
 ].map(r=>r.map(esc)));
body+=`<p>Validação na versão publicada: ${login?.resultados.length||0}/15 cenários de login com respostas controladas e ${busca?.resultados.filter(x=>x.ok).length||0}/32 recuperações de busca seguidas de criação de orçamento/OS. Login simulado não envia tentativas ao provedor. Os demais testes usam a API real das empresas fictícias.</p>`;
body+='<h2>Conferência complementar</h2>'+table(['Camada','Resultado'],[['Banco publicado: aprovação, estoque, pagamento, garantia e relatório',`${banco.filter(b=>b.ok).length}/16 perfis concluídos`],['Jornada completa pela interface',`${ciclo.filter(b=>b.ok).length}/16 perfis concluídos`],['Concorrência, resposta perdida e layout estreito',`${excecoes?.resultados.filter(x=>x.ok).length||0}/16 perfis concluídos`],['PDFs gerados e conferidos',`${pdfs?.resultados.length||0}`],['Suítes locais',`${sum.suitesOk||0}/${sum.suites||0}`]]);
if(concorrencia)body+='<h2>Repetição simultânea na versão publicada</h2><p>'+esc(concorrencia.metodo)+'</p>'+table(['Camada','Resultado'],[['Criação, edição, consulta e PDF em paralelo',`${concorrencia.casos.length}/12 casos completos`],['Leituras adicionais de alertas e detalhes',`${concorrencia.rpc.filter(x=>x.ok).length}/${concorrencia.rpc.length}`],['Falhas nos fluxos de interface',concorrencia.falhas.length]])+'<p><a href="concorrencia-publicado/resultado.json">Resultado e tempos da repetição simultânea</a>. Essa repetição é adicional à matriz de 128 casos; suas medições não foram misturadas com as anteriores.</p>';
body+='<h2>Cada subsistema</h2>'+table(['Subsistema','Casos de interface','Integrações de banco','Jornada UI'],Object.keys(nomes).map(p=>[esc(nomes[p]),`${docs.filter(d=>d.perfil===p).length}/8`,banco.find(b=>b.perfil===p)?.ok?'OK':'Pendente / falha',ciclo.find(b=>b.perfil===p)?.ok?'OK':'Pendente / falha']));
body+=`<h2>Falhas da matriz principal e retestes</h2><p>Falhas de produto/servidor abaixo são distintas de ajustes de seletores dos roteiros-piloto. Estes últimos foram mantidos nas pastas de piloto, sem serem contados como correções do software.</p>`+table(['Subsistema / tela','Caso / etapa','Erro original','Cobertura final'],falhas.map(f=>[esc(nomes[f.perfil]+' / '+f.width),esc((f.caso||'login')+' / '+f.etapa),esc(f.erro),docs.filter(d=>d.perfil===f.perfil&&d.width===f.width).length+'/4']));
body+='<h2>Detalhamento das jornadas complementares</h2><p>Em Vidros, o roteiro tentou concluir um serviço suspenso. O sistema bloqueou corretamente; a preparação do teste foi ajustada. Isso não foi contado como bug do produto. Os arquivos de banco preservam as falhas e tempos de suas tentativas anteriores.</p>';
for(const perfil of Object.keys(nomes)){
 const b=banco.find(x=>x.perfil===perfil),u=ciclo.find(x=>x.perfil===perfil),e=excecoes?.resultados.find(x=>x.perfil===perfil);
 body+=`<details class="card"><summary>${esc(nomes[perfil])} — evidências e verificações</summary><p><a href="banco/${perfil}.json">Banco e tempos</a> · <a href="banco/ui-${perfil}.json">Jornada na interface</a></p>`;
 for(const [nome,cs] of [['Banco',b?.checks],['Interface',u?.checks],['Exceções e layout',e?.checks]])body+='<h3>'+nome+'</h3><ul>'+(cs||[]).map(c=>'<li>'+esc(typeof c==='string'?c:c.nome+(c.width?' · '+c.width+' px':''))+'</li>').join('')+'</ul>';
 body+='</details>';
}
body+=`<h2>Evidências</h2><p><a href="sumario.json">Matriz e medições em JSON</a> · <a href="pdfs-conferencia.json">Conferência dos PDFs</a> · <a href="regressao/resultado.json">Regressão local</a> · <a href="diagnostico-timeouts.json">Logs de tempo limite</a></p><p>Build inicial: <code>${esc(rodadas[0]?.build)}</code>. Publicação da correção: <code>${esc(publicacao?.build||'a conferir')}</code>.</p>`;
await writeFile(root+'/relatorio.html',header('Assistência, manutenção e limpeza — testes e tempos',body));
for(const [g,nome] of Object.entries(grupos)){
 const items=docs.filter(d=>d.ramo===g),measure=tempos.filter(t=>t.ramo===g);
 let b=method+'<h2>Tempos por operação</h2>'+table(['Operação','Amostras','Mediana','P95','Maior'],Object.entries(resumo[g].tempos).map(([n,t])=>[esc(n),t.n,sec(t.mediana),sec(t.p95),sec(t.maximo)]));
 b+='<h2>Todos os documentos</h2>'+table(['Subsetor','Tela / cenário','Número','Total final interno','Evidências'],items.map(d=>[esc(nomes[d.perfil]),esc(d.width+' px / '+d.caso),'#'+d.numero,esc(new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(d.valorEditado/100)),`<a href="${d.pasta}/${d.pdf}">PDF</a> · <a href="${d.pasta}/${d.perfil}-${d.width}-${d.caso}-resumo.png">Resumo</a> · <a href="${d.pasta}/${d.perfil}-${d.width}-${d.caso}-itens.png">Itens</a> · <a href="${d.pasta}/${d.perfil}-${d.width}-${d.caso}-historico.png">Histórico</a>`]));
 b+='<h2>Cada operação medida</h2><input id="busca" placeholder="Filtrar subsetor, caso ou operação…" aria-label="Filtrar testes">'+table(['Subsetor','Tela','Caso','Operação','Segundos','Cliques / campos','Rodada'],measure.map(t=>[esc(nomes[t.perfil]),t.width,esc(t.caso),esc(t.nome),sec(t.segundos),t.cliques+' / '+t.campos,esc(t.pasta.startsWith('retestes')?'Sequencial':'Inicial simultânea')]));
 b+='<script>document.querySelector("#busca").addEventListener("input",e=>{for(const r of e.target.nextElementSibling.querySelectorAll("tbody tr"))r.hidden=!r.textContent.toLocaleLowerCase().includes(e.target.value.toLocaleLowerCase())})</script>';
 await writeFile(root+'/'+arquivos[g],header(nome+' — casos e medições',b));
}
console.log(JSON.stringify({documentos:docs.length,tempos:tempos.length,checks:checks.length,falhas:falhas.length,banco:banco.filter(b=>b.ok).length,ciclo:ciclo.filter(b=>b.ok).length}));
